def transform(grid):
    """Expand the centered 2 into a diagonal V, then continue a 4-column 1 pattern."""
    n = len(grid[0])
    center = grid[0].index(2)
    out = [[0 for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if r <= center and abs(c - center) == r:
                out[r][c] = 2
            elif r >= 3 and (c - r - center) % 4 == 0 and c + r >= center + 2 and c - r <= center - 4:
                out[r][c] = 1
    return out
